structure.mermaidSource:
flowchart TD
  start["Início: Isolar a forma 'a' ou 'o' no período"] --> dec_subst{"Antecede substantivo concordando em gênero e número?"}
  dec_subst -- "Sim (Determina substantivo)" --> res_artigo["Classificar como ARTIGO DEFINIDO"]
  dec_subst -- "Não (Sem substantivo regido)" --> dec_verbo{"Está vinculado a um verbo como complemento objeto?"}
  dec_verbo -- "Não (Desvinculado de verbo)" --> res_outra_classe["Investigar outras classes: Pronome Demonstrativo ('aquela/aquele') ou Preposição"]
  dec_verbo -- "Sim (Vinculado a verbo transitivo)" --> proc_teste_reto["Substituir 'a/o' pelo pronome reto correspondente ('ela/ele')"]
  proc_teste_reto --> dec_reto{"A substituição indica com clareza o paciente/alvo da ação verbal?"}
  dec_reto -- "Sim ('Não a vi' -> 'Não vi ela')" --> res_obliquo["Classificar como PRONOME PESSOAL OBLÍQUO ÁTONO"]
  dec_reto -- "Não" --> res_outra_classe

flowchart TD
  start["Início: Isolar a forma 'a' antecedendo termo nominal"] --> dec_num_subst{"Substantivo subsequente está no plural?"}
  dec_num_subst -- "Sim" --> dec_a_singular{"A forma 'a' permanece no singular invariável?"}
  dec_num_subst -- "Não" --> proc_flexao_hipotetica["Flexionar substantivo mentalmente para o plural"]
  dec_a_singular -- "Sim" --> proc_checar_regente["Verificar se o termo regente exige preposição 'a'"]
  dec_a_singular -- "Não" --> res_artigo_plural["Resultado: Artigo feminino plural 'as' ou crase 'às'"]
  proc_flexao_hipotetica --> dec_comportamento_plural{"Ao flexionar para o plural, 'a' permanece no singular?"}
  dec_comportamento_plural -- "Sim" --> proc_checar_regente
  dec_comportamento_plural -- "Não" --> res_artigo_definido["Resultado: Artigo Definido singular (varia para 'as')"]
  proc_checar_regente --> dec_regencia{"Termo anterior rege preposição 'a'?"}
  dec_regencia -- "Sim" --> res_preposicao_pura["Resultado: 100% Preposição Pura confirmada"]
  dec_regencia -- "Não" --> res_preposicao_sem_regente["Resultado: Preposição acidental ou locução (revisar sintaxe)"]
